<?php require_once __DIR__.'/includes/auth.php'; require_login(); $stmt=db()->prepare('SELECT e.employee_number,e.job_title,a.work_date,a.clock_in,a.clock_out,a.worked_minutes,a.status FROM attendance_records a JOIN employees e ON e.id=a.employee_id WHERE e.user_id=? ORDER BY a.work_date DESC'); $stmt->execute([$_SESSION['user_id']]); header('Content-Type:text/csv'); header('Content-Disposition:attachment; filename=attendance.csv'); $out=fopen('php://output','w'); fputcsv($out,['Employee number','Job title','Date','Clock in','Clock out','Worked minutes','Status']); while($row=$stmt->fetch(PDO::FETCH_ASSOC)) fputcsv($out,$row); fclose($out); exit; ?>
